	'i_mod_m2b3' => 'Batterien, Generatoren, Motoren und Stromverteilung',
	'i_mod_m2b4' => 'Werkstattpraxis mit Multimetern, Oszilloskopen und Löttechniken',
	'i_mod_m3b1' => 'Luftfahrtmetalle, Verbundwerkstoffe, Korrosion und Korrosionsschutz',
	'i_mod_m3b2' => 'Verbindungselemente, Sicherungsdraht, Splinte und Drehmomentpraxis',
	'i_mod_m3b3' => 'Handwerkzeuge, Messtechnik und Kalibrierdisziplin',
