	'le_m6a' => 'Prüfstandstest und schriftliche Prüfung',
	'le_m6h' => '300 h',
	'le_m6m' => 'Monate 10–12',
	'le_m6n' => 'M6 Avionik & Instrumente',
	'le_m7a' => 'Laufende Fallprüfungen',
	'le_m7h' => '120 h',
	'le_m7m' => 'Monate 1–18',
	'le_m7n' => 'M7 Human Factors & Vorschriften',
	'le_m8a' => 'Beaufsichtigte Abzeichnungen und Abschlussbeurteilung',
	'le_m8h' => '340 h',
	'le_m8m' => 'Monate 13–18',
	'le_m8n' => 'M8 Hangarpraxis & Typeneinweisung',
	'le_p' => 'Jedes Modul erfüllt spezifische Kenntnis- und Praxisanforderungen nach den Vorgaben der Zivilluftfahrtbehörden. Der Ausbildungsfortschritt wird durch schriftliche Prüfungen, Prüfstandstests, mündliche Überprüfungen und gegengezeichnete Arbeitskarten nachgewiesen. Die Lizenzprüfungen der nationalen Luftfahrtbehörde werden separat abgelegt, wobei das College sämtliche Vorbereitungen sowie die beglaubigten Ausbildungsnachweise bereitstellt.',
	'le_th1' => 'Modul',
